cat > /tmp/rustrepo/src/main.rs << 'EOF'
use std::collections::HashMap;

fn fibonacci(n: u64) -> u64 {
    if n <= 1 {
        return n;
    }
    let mut a = 0u64;
    let mut b = 1u64;
    for _ in 2..=n {
        let temp = a + b;
        a = b;
        b = temp;
    }
    b
}

fn factorial(n: u64) -> u64 {
    if n == 0 {
        return 1;
    }
    (1..=n).product()
}

fn binary_search(arr: &[i32], target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = arr.len();
    while left < right {
        let mid = left + (right - left) / 2;
        match arr[mid].cmp(&target) {
            std::cmp::Ordering::Equal => return Some(mid),
            std::cmp::Ordering::Less => left = mid + 1,
            std::cmp::Ordering::Greater => right = mid,
        }
    }
    None
}

struct WordCounter {
    counts: HashMap<String, usize>,
}

impl WordCounter {
    fn new() -> Self {
        WordCounter {
            counts: HashMap::new(),
        }
    }

    fn add_text(&mut self, text: &str) {
        for word in text.split_whitespace() {
            let word = word.to_lowercase();
            let count = self.counts.entry(word).or_insert(0);
            *count += 1;
        }
    }

    fn get_count(&self, word: &str) -> usize {
        *self.counts.get(&word.to_lowercase()).unwrap_or(&0)
    }

    fn top_words(&self, n: usize) -> Vec<(&str, usize)> {
        let mut items: Vec<(&str, usize)> = self
            .counts
            .iter()
            .map(|(k, v)| (k.as_str(), *v))
            .collect();
        items.sort_by(|a, b| b.1.cmp(&a.1));
        items.truncate(n);
        items
    }
}

fn main() {
    println!("Fibonacci(10) = {}", fibonacci(10));
    println!("Factorial(5) = {}", factorial(5));

    let arr = vec![1, 3, 5, 7, 9, 11, 13];
    println!("Binary search for 7: {:?}", binary_search(&arr, 7));

    let mut counter = WordCounter::new();
    counter.add_text("hello world hello rust programming");
    println!("Count of 'hello': {}", counter.get_count("hello"));
    println!("Top 3 words: {:?}", counter.top_words(3));
}
EOF

cd /tmp/rustrepo && git init && git add . && git commit -m "Initial Rust code"
echo "Done"

