# Now let me create the cache module
cat > /workspace/src/gittype/cache.py << 'CACHEEOF'
"""Cache management for gittype"""
import os
import json
import hashlib
import gzip
import struct
import uuid
from pathlib import Path


def get_gittype_dir() -> Path:
    """Get the main gittype data directory"""
    return Path.home() / '.gittype'


def get_cache_dir() -> Path:
    """Get the challenge cache directory"""
    return get_gittype_dir() / 'cache'


def get_repos_dir() -> Path:
    """Get the repository cache directory"""
    return get_gittype_dir() / 'repos'


def get_db_path() -> Path:
    """Get the SQLite database path"""
    return get_gittype_dir() / 'gittype.db'


def get_logs_dir() -> Path:
    """Get the logs directory"""
    return get_gittype_dir() / 'logs'


def get_custom_theme_path() -> Path:
    """Get the custom theme file path"""
    return get_gittype_dir() / 'custom-theme.json'


def get_settings_path() -> Path:
    """Get the settings file path"""
    return get_gittype_dir() / 'settings.json'


def ensure_dirs():
    """Ensure all required directories exist"""
    get_gittype_dir().mkdir(parents=True, exist_ok=True)
    get_logs_dir().mkdir(parents=True, exist_ok=True)


def get_cache_stats() -> dict:
    """Get statistics about the cache"""
    cache_dir = get_cache_dir()
    if not cache_dir.exists():
        return {'count': 0, 'size': 0}

    files = list(cache_dir.glob('*.bin'))
    total_size = sum(f.stat().st_size for f in files)
    return {'count': len(files), 'size': total_size}


def clear_cache():
    """Clear all cached challenges"""
    import shutil
    cache_dir = get_cache_dir()
    if cache_dir.exists():
        shutil.rmtree(str(cache_dir))


def list_cache() -> list:
    """List cached repository keys"""
    cache_dir = get_cache_dir()
    if not cache_dir.exists():
        return []
    return [f.stem for f in cache_dir.glob('*.bin')]


def compute_cache_key(repo_spec: str) -> str:
    """Compute the SHA-256 hash for a cache key"""
    return hashlib.sha256(repo_spec.encode()).hexdigest()


def read_challenge_cache(cache_key: str) -> list:
    """Read challenges from cache. Returns list of Challenge dicts or None."""
    cache_dir = get_cache_dir()
    cache_file = cache_dir / f'{cache_key}.bin'

    if not cache_file.exists():
        return None

    try:
        with open(str(cache_file), 'rb') as f:
            compressed = f.read()
        data = gzip.decompress(compressed)
        return decode_challenges(data)
    except Exception:
        return None


def write_challenge_cache(cache_key: str, repo_identifier: str, 
                          commit_hash: str, challenges: list):
    """Write challenges to cache"""
    cache_dir = get_cache_dir()
    cache_dir.mkdir(parents=True, exist_ok=True)

    cache_file = cache_dir / f'{cache_key}.bin'

    data = encode_challenges(repo_identifier, commit_hash, challenges)
    compressed = gzip.compress(data)

    with open(str(cache_file), 'wb') as f:
        f.write(compressed)


def encode_str(s: str) -> bytes:
    """Encode a string with varint length prefix"""
