            return val

    def read_str():
        n = read_varint()
        s = data[pos:pos+n].decode('utf-8'); 
        nonlocal pos; pos += n
        return s

    def read_opt_str():
        nonlocal pos
        o = data[pos]; pos += 1
        if o == 1:
            return read_str()
        return None

    def read_opt_u32():
        nonlocal pos
        o = data[pos]; pos += 1
        if o == 1:
            return read_varint()
        return None

    # Read key prefix and commit hash  
    prefix = read_str()
    commit = read_str()

    count = read_varint()
    challenges = []

    for _ in range(count):
        ch_id = read_str()
        file_path = read_opt_str()
        start_line = read_opt_u32()
        end_line = read_opt_u32()
        language = read_opt_str()

        # comment_ranges: Option<Vec<(u32, u32)>>
        cr_opt = data[pos]; pos += 1
        comment_ranges = []
        if cr_opt == 1:
            cr_len = read_varint()
            for _ in range(cr_len):
                cs = read_varint()
                ce = read_varint()
                comment_ranges.append((cs, ce))

        # difficulty: Option<u8>
        diff_opt = data[pos]; pos += 1
        difficulty = None
        if diff_opt == 1:
            difficulty = data[pos]; pos += 1

        challenges.append({
            'id': ch_id,
            'file_path': file_path,
            'start_line': start_line,
            'end_line': end_line,
            'language': language,
            'comment_ranges': comment_ranges,
            'difficulty': difficulty,
        })

