        c = self._colors.get(key, {"r": 128, "g": 128, "b": 128})
        return (c['r'], c['g'], c['b'])

    def __getattr__(self, name: str) -> Tuple[int, int, int]:
        return self.get_rgb(name)


class ThemeManager:
    """Manages themes for the application"""

    def __init__(self):
        self._themes = {}
        self._current_theme_id = "default"
        self._is_dark = True
        self._load_builtin_themes()
        self._load_custom_theme()
        self._load_settings()

    def _get_themes_dir(self) -> Path:
        """Get the themes directory"""
        # First try relative to executable
        exe_dir = Path(os.path.dirname(os.path.abspath(__file__))).parent.parent
        themes_dir = exe_dir / 'assets' / 'themes'
        if themes_dir.exists():
            return themes_dir
        # Try relative to current dir
        themes_dir = Path('assets') / 'themes'
        if themes_dir.exists():
            return themes_dir
        return None

    def _load_builtin_themes(self):
        """Load all built-in themes from assets"""
        # Add default theme from hardcoded data
        self._themes['default'] = DEFAULT_THEME

        themes_dir = self._get_themes_dir()
        if themes_dir:
            for theme_file in themes_dir.glob('*.json'):
                try:
                    with open(str(theme_file), 'r') as f:
                        theme = json.load(f)
                    theme_id = theme.get('id', theme_file.stem)
                    self._themes[theme_id] = theme
                except Exception:
                    pass

    def _load_custom_theme(self):
        """Load custom theme if it exists"""
        from .cache import get_custom_theme_path
        custom_path = get_custom_theme_path()
        if custom_path.exists():
            try:
                with open(str(custom_path), 'r') as f:
                    custom = json.load(f)
                self._themes['custom'] = {
                    'id': 'custom',
                    'name': 'Custom',
                    'description': 'Custom user theme',
                    **custom
                }
            except Exception:
                pass

    def _load_settings(self):
        """Load theme settings"""
        from .cache import get_settings_path
        settings_path = get_settings_path()
        if settings_path.exists():
            try:
                with open(str(settings_path), 'r') as f:
                    settings = json.load(f)
                self._current_theme_id = settings.get('theme', 'default')
                self._is_dark = settings.get('color_mode', 'dark') == 'dark'
            except Exception:
                pass

    def save_settings(self):
        """Save theme settings"""
        from .cache import get_settings_path, ensure_dirs
        ensure_dirs()
        settings_path = get_settings_path()
        settings = {
            'theme': self._current_theme_id,
            'color_mode': 'dark' if self._is_dark else 'light',
        }
        try:
            with open(str(settings_path), 'w') as f:
                json.dump(settings, f, indent=2)
        except Exception:
            pass

    @property
    def current_colors(self) -> ThemeColors:
        """Get current theme colors"""
        theme = self._themes.get(self._current_theme_id, DEFAULT_THEME)
        mode = 'dark' if self._is_dark else 'light'
        colors = theme.get(mode, theme.get('dark', DEFAULT_THEME['dark']))
        return ThemeColors(colors)

    @property
    def current_theme_id(self) -> str:
        return self._current_theme_id

    @property
    def is_dark(self) -> bool:
        return self._is_dark

    @is_dark.setter
    def is_dark(self, value: bool):
        self._is_dark = value

    def set_theme(self, theme_id: str):
        """Set the current theme"""
        if theme_id in self._themes:
            self._current_theme_id = theme_id

    def get_theme_names(self) -> list:
        """Get list of available theme names"""
        order = ['Default', 'Original', 'ASCII', 'Aurora', 'Blood Oath', 
                 'Cyber Void', 'Eclipse', 'Glacier', 'Inferno', 'Neon Abyss',
                 'Oblivion', 'Runic', 'Spectral', 'Starforge', 'Venom', 'Custom']
        themes = []
        for t in self._themes.values():
            name = t.get('name', t.get('id', ''))
            if name not in themes:
                themes.append(name)
        # Sort by predefined order
        def sort_key(name):
            try:
                return order.index(name)
            except ValueError:
                return len(order)
        themes.sort(key=sort_key)
        return themes

    def get_theme_by_name(self, name: str) -> Optional[Dict]:
        """Get theme by display name"""
        for t in self._themes.values():
            if t.get('name', '') == name:
                return t
        return None

    def get_theme_description(self, name: str) -> str:
        """Get theme description"""
        theme = self.get_theme_by_name(name)
        if theme:
            return theme.get('description', '')
        return ''


# Global theme manager instance
_theme_manager = None


def get_theme_manager() -> ThemeManager:
    """Get the global theme manager"""
    global _theme_manager
    if _theme_manager is None:
        _theme_manager = ThemeManager()
    return _theme_manager
THEMEEOF
