"""Git repository information"""
import os
import subprocess
from typing import Optional, Tuple
from pathlib import Path


class GitInfo:
    """Information about a git repository"""
    def __init__(self, path: str):
        self.path = path
        self.branch = None
        self.commit_hash = None
        self.is_dirty = False
        self.remote_url = None
        self.user_name = None
        self.repo_name = None
        self._load()

    def _run_git(self, *args) -> Optional[str]:
        """Run a git command and return output"""
        try:
            result = subprocess.run(
                ['git', '-C', self.path] + list(args),
                capture_output=True, text=True, timeout=10
            )
            if result.returncode == 0:
                return result.stdout.strip()
            return None
        except Exception:
            return None

    def _load(self):
        """Load git information"""
        # Check if this is a git repo
        git_dir = self._run_git('rev-parse', '--git-dir')
        if not git_dir:
            return

        # Branch
        self.branch = self._run_git('rev-parse', '--abbrev-ref', 'HEAD')

        # Commit hash
        commit = self._run_git('rev-parse', 'HEAD')
        if commit:
            self.commit_hash = commit[:8]  # Short hash

        # Dirty status
        status = self._run_git('status', '--porcelain')
        self.is_dirty = bool(status and status.strip())

        # Remote URL
        self.remote_url = self._run_git('remote', 'get-url', 'origin')
        if not self.remote_url:
            self.remote_url = self._run_git('remote', 'get-url', '--all', 'origin')

        # Parse user/repo from remote URL
        if self.remote_url:
            self.user_name, self.repo_name = parse_remote_url(self.remote_url)

        if not self.user_name:
            self.user_name = 'local'
        if not self.repo_name:
            # Use directory name
            self.repo_name = os.path.basename(os.path.abspath(self.path))
            if not self.repo_name:
                self.repo_name = 'unknown'


def parse_remote_url(url: str) -> Tuple[Optional[str], Optional[str]]:
    """Parse user and repo name from a git remote URL"""
    import re

    # HTTPS: https://github.com/user/repo.git or https://github.com/user/repo
    m = re.match(r'https?://(?:www\.)?github\.com/([^/]+)/([^/.]+)(?:\.git)?', url)
    if m:
        return m.group(1), m.group(2)

    # SSH: git@github.com:user/repo.git
    m = re.match(r'git@github\.com:([^/]+)/([^/.]+)(?:\.git)?', url)
    if m:
        return m.group(1), m.group(2)

    # Other formats
    parts = url.rstrip('/').rstrip('.git').split('/')
    if len(parts) >= 2:
        return parts[-2], parts[-1]

    return None, None


def find_git_root(path: str) -> Optional[str]:
    """Find the root of the git repository"""
    try:
        result = subprocess.run(
            ['git', '-C', path, 'rev-parse', '--show-toplevel'],
            capture_output=True, text=True, timeout=10
        )
        if result.returncode == 0:
            return result.stdout.strip()
    except Exception:
        pass
    return None
