class RecordsScreen(Screen):
    """Session records screen"""
    def __init__(self, app):
        super().__init__(app)
        self.sessions = []
        self.selected = 0
        self.filter_days = 30
        self.sort_key = "date"
        self.sort_asc = False
        self._load_sessions()

    def _load_sessions(self):
        try:
            from ..database import get_recent_sessions
            self.sessions = get_recent_sessions(50, self.filter_days)
        except Exception:
            self.sessions = []

    def handle_key(self, key):
        if key in (curses.KEY_UP, ord("k"), ord("K")):
            self.selected = max(0, self.selected - 1)
        elif key in (curses.KEY_DOWN, ord("j"), ord("J")):
            self.selected = min(len(self.sessions) - 1, self.selected + 1) if self.sessions else 0
        elif key == ord(" "):
            pass  # show details
        elif key in (ord("f"), ord("F")):
            pass  # filter
        elif key in (ord("s"), ord("S")):
            pass  # sort
        elif key in (ord("r"), ord("R")):
            self._load_sessions()
        elif key == 27:
            self.app.show_title()

    def draw(self):
        s = self.stdscr
        s.erase()
        h, w = s.getmaxyx()

        # Header
        draw_box(s, 0, 0, 3, w, "Session Records", color(CP_BORDER))
        try:
            s.attron(color(CP_TITLE) | curses.A_BOLD)
            s.addstr(1, 2, "Records - Typing Session Records")
            s.attroff(color(CP_TITLE) | curses.A_BOLD)
        except curses.error:
            pass

        # Filter/sort info
        count = len(self.sessions)
        info = f"  Filter: Last {self.filter_days} days | Sort: Date \u2193 | Sessions: {count}"
        try:
            s.attron(color(CP_TEXT))
            s.addstr(2, 0, info[:w-1])
            s.attroff(color(CP_TEXT))
        except curses.error:
            pass

        # Sessions list
        list_y = 3
        list_h = h - list_y - 1
        draw_box(s, list_y, 0, list_h, w, "Sessions", color(CP_BORDER))

        if not self.sessions:
            center_text(s, list_y + list_h // 2, "No typing sessions found for the selected time period.", color(CP_TEXT))
            center_text(s, list_y + list_h // 2 + 1, "Start typing to build your records!", color(CP_INFO))
        else:
            for i, sess in enumerate(self.sessions[:list_h - 2]):
                row_y = list_y + 1 + i
                attr = color(CP_HIGHLIGHT) | curses.A_BOLD if i == self.selected else color(CP_TEXT)
                row = f"  {sess.get('created_at', 'N/A')[:16]}  CPM: {sess.get('cpm', 0):.0f}  WPM: {sess.get('wpm', 0):.0f}  Acc: {sess.get('accuracy', 0):.1f}%"
                try:
                    s.attron(attr)
                    s.addstr(row_y, 0, row[:w-1])
                    s.attroff(attr)
                except curses.error:
                    pass

        # Footer
        footer = "  [\u2191\u2193/JK] Navigate  [SPACE] Details  [F] Filter  [S] Sort  [R] Refresh  [ESC] Back"
        try:
            s.attron(color(CP_KEY_NAV))
            s.addstr(h - 1, 0, footer[:w-1])
            s.attroff(color(CP_KEY_NAV))
        except curses.error:
            pass


class AnalyticsScreen(Screen):
    """Analytics/stats screen"""
    def __init__(self, app):
        super().__init__(app)
        self.view_idx = 0
        self.views = ["Overview", "Trends", "Repositories", "Languages"]

    def handle_key(self, key):
        if key in (curses.KEY_LEFT, ord("h"), ord("H")):
            self.view_idx = (self.view_idx - 1) % len(self.views)
        elif key in (curses.KEY_RIGHT, ord("l"), ord("L")):
            self.view_idx = (self.view_idx + 1) % len(self.views)
        elif key in (ord("r"), ord("R")):
            pass  # refresh
        elif key == 27:
            self.app.show_title()

    def draw(self):
        s = self.stdscr
        s.erase()
        h, w = s.getmaxyx()

        # Header
        draw_box(s, 0, 0, 3, w, "GitType Analytics", color(CP_BORDER))
        try:
            s.attron(color(CP_TITLE) | curses.A_BOLD)
            s.addstr(1, 2, "Performance Analytics")
            s.attroff(color(CP_TITLE) | curses.A_BOLD)
        except curses.error:
            pass

        # View tabs
        draw_box(s, 3, 0, 3, w, "Views", color(CP_BORDER))
        try:
            tabs = ""
            for i, v in enumerate(self.views):
                if i == self.view_idx:
                    s.attron(color(CP_TEXT) | curses.A_BOLD)
                    s.addstr(4, 2 + len(tabs), v)
                    s.attroff(color(CP_TEXT) | curses.A_BOLD)
                else:
                    s.attron(color(CP_TEXT_SEC))
                    s.addstr(4, 2 + len(tabs), v)
                    s.attroff(color(CP_TEXT_SEC))
                tabs += v
                if i < len(self.views) - 1:
                    s.attron(color(CP_TEXT))
                    s.addstr(4, 2 + len(tabs), " | ")
                    s.attroff(color(CP_TEXT))
                    tabs += " | "
        except curses.error:
            pass

        # Content area
        content_y = 6
        content_h = h - content_y - 1

        view = self.views[self.view_idx]
        self._draw_view(s, view, content_y, content_h, w)

        # Footer
        footer = "  [\u2190\u2192/HL] Switch View  [\u2191\u2193/JK] Navigate  [R] Refresh  [ESC] Back"
        try:
            s.attron(color(CP_KEY_NAV))
            s.addstr(h - 1, 0, footer[:w-1])
            s.attroff(color(CP_KEY_NAV))
        except curses.error:
            pass

    def _draw_view(self, s, view, y, h, w):
        if view == "Overview":
            self._draw_overview(s, y, h, w)
        elif view == "Trends":
            self._draw_trends(s, y, h, w)
        elif view == "Repositories":
            self._draw_repos(s, y, h, w)
        elif view == "Languages":
            self._draw_langs(s, y, h, w)

    def _draw_overview(self, s, y, h, w):
        draw_box(s, y, 0, h, w, "", color(CP_BORDER))
        center_text(s, y + h // 2, "No performance data available yet - start typing to see stats!", color(CP_TEXT))

    def _draw_trends(self, s, y, h, w):
        # Split into CPM and Accuracy trends
        half_h = h // 2
        draw_box(s, y, 0, half_h, w, "CPM Trend", color(CP_BORDER))
        center_text(s, y + 2, "No trend data available - keep typing to build your performance history!", color(CP_TEXT))
        draw_box(s, y + half_h, 0, h - half_h, w, "Accuracy Trend", color(CP_BORDER))
        center_text(s, y + half_h + 2, "No accuracy trend data available - keep typing to build your accuracy history!", color(CP_TEXT))

    def _draw_repos(self, s, y, h, w):
        # Split into repo list and details
        half_w = w // 2
        draw_box(s, y, 0, h, half_w, "Repositories", color(CP_BORDER))
        try:
            s.attron(color(CP_TEXT_SEC))
            s.addstr(y + 1, 2, "\u25ba No repositories available")
            s.attroff(color(CP_TEXT_SEC))
