        if theme_name in self.theme_names:
            self.theme_selected = self.theme_names.index(theme_name)

    def handle_key(self, key):
        if key in (curses.KEY_LEFT, ord("h"), ord("H")):
            self.tab_idx = (self.tab_idx - 1) % len(self.tabs)
        elif key in (curses.KEY_RIGHT, ord("l"), ord("L")):
            self.tab_idx = (self.tab_idx + 1) % len(self.tabs)
        elif key in (curses.KEY_UP, ord("k"), ord("K")):
            if self.tab_idx == 0:
                self.color_selected = max(0, self.color_selected - 1)
