    def show_settings(self):
        logger.info("Initializing screen: Settings")
        self.current_screen = SettingsScreen(self)

    def show_help(self):
        logger.info("Initializing screen: Help")
        self.current_screen = HelpScreen(self)

    def quit(self):
        self.running = False

    def _draw(self):
        try:
            if self.current_screen:
                self.current_screen.draw()
            self.stdscr.refresh()
        except Exception as e:
            logger.debug(f"Draw error: {e}")

    def run(self):
        """Main event loop"""
        self.stdscr.timeout(100)  # 100ms timeout for getch
        while self.running:
            try:
                key = self.stdscr.getch()
            except KeyboardInterrupt:
                break
            except Exception:
                key = -1

            if key != -1 and self.current_screen:
                self.current_screen.handle_key(key)

            if isinstance(self.current_screen, TypingScreen):
                self.current_screen.update()

            self._draw()


