class TrendingScreen(Screen):
    """Trending repositories screen"""
    def __init__(self, app, language, repo_name, period):
        super().__init__(app)
        self.language = language
        self.repo_name = repo_name
        self.period = period
        self.repos = []
        self.selected = 0
        self.loading = True
        self.error = None

    def on_enter(self):
        self._load_trending()

    def _load_trending(self):
        self.repos = []
        self.loading = False
        self.error = "No internet connection available"

    def handle_key(self, key):
        if key in (curses.KEY_UP, ord("k")):
            self.selected = max(0, self.selected - 1)
        elif key in (curses.KEY_DOWN, ord("j")):
            self.selected = min(len(self.repos) - 1, self.selected + 1)
        elif key == ord(" ") or key == 10:
            if self.repos:
                self.app.play_trending_repo(self.repos[self.selected])
        elif key == 27:
            self.app.quit()

    def draw(self):
        s = self.stdscr
        s.erase()
        h, w = s.getmaxyx()
        title = "Trending GitHub Repositories"
        if self.language:
            title += f" - {self.language}"
        draw_box(s, 0, 0, 3, w, title, color(CP_BORDER))
        if self.loading:
            center_text(s, h // 2, "Loading trending repositories...", color(CP_INFO))
        elif self.error:
            center_text(s, h // 2, self.error, color(CP_ERROR))
        else:
            for i, repo in enumerate(self.repos[:h-4]):
                attr = color(CP_HIGHLIGHT) if i == self.selected else color(CP_TEXT)
                try:
                    s.attron(attr)
                    s.addstr(3 + i, 2, str(repo)[:w-4])
                    s.attroff(attr)
                except curses.error:
                    pass
        footer = "  [\u2191\u2193/JK] Navigate  [SPACE/ENTER] Select  [ESC] Back"
        try:
            s.attron(color(CP_KEY_NAV))
            s.addstr(h - 1, 0, footer[:w-1])
            s.attroff(color(CP_KEY_NAV))
        except curses.error:
            pass


class GameApp:
    """Main game application"""
    def __init__(self, stdscr, repo_path, repo_spec, lang_list):
        self.stdscr = stdscr
        self.repo_path = repo_path
        self.repo_spec = repo_spec
        self.lang_list = lang_list
        self.running = True
        self.current_screen = None
        self.challenges = []
        self.git_info = None
        self.theme_manager = get_theme_manager()
        self._prev_summary = None
        self._setup()

    def _setup(self):
        curses.curs_set(0)
        self.stdscr.nodelay(True)
        self.stdscr.keypad(True)
        init_colors(self.theme_manager.current_colors)

        # Show loading screen while loading challenges
        loading = LoadingScreen(self)
        self.current_screen = loading
        self._draw()

        # Load challenges in background
        self._load_challenges_async(loading)

    def _load_challenges_async(self, loading_screen):
        """Load challenges (may take time for git operations)"""
        import threading
        result = {"challenges": [], "error": None, "git_info": None}
        done = threading.Event()

        def load():
            try:
                repo_path = self.repo_path
                if repo_path:
                    git_root = find_git_root(os.path.abspath(repo_path))
                    if git_root:
                        result["git_info"] = GitInfo(git_root)
                    else:
                        result["git_info"] = GitInfo(os.path.abspath(repo_path))
                loading_screen.message = "Loading challenges..."
                self._draw()
                from ..game import load_challenges
                result["challenges"] = load_challenges(repo_path, self.repo_spec, self.lang_list)
            except Exception as e:
                result["error"] = str(e)
            done.set()

        t = threading.Thread(target=load, daemon=True)
        t.start()

        # Wait with timeout, updating screen
        start = time.time()
        while not done.is_set():
            if time.time() - start > 30:
                result["error"] = "Timeout loading challenges"
                break
            self._draw()
            time.sleep(0.05)
            # Handle quit during loading
            try:
                key = self.stdscr.getch()
                if key == 27 or key == ord("q"):
                    self.running = False
                    return
            except Exception:
                pass

        self.challenges = result["challenges"]
        self.git_info = result["git_info"]

        if result["error"]:
            logger.error(f"Repository processing failed: {result['error']}")
            loading_screen.error = result["error"]
            self._draw()
            time.sleep(1)
        else:
            logger.info("Repository processing completed successfully")

        # Go to title screen
        self.show_title()

